import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useNavigate, useParams } from "react-router-dom";

import DialogAdditionalFeatures from "src/views/dialog/IT-Solution-Features/DialogAdditionalFeatures";
import TableAdditionalFeatures from "src/views/tables/IT-Solution-Features/TableAdditionalFeatures";

const ITSolutionAdditionalFeaturesPage = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [subFeaturesData, setSubFeaturesData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");
  const { id } = useParams();
  // Testimonials
  const [subFeaturesFormDialogOpen, setSubFeaturesFormDialogOpen] =
    useState(false);
  const [subFeaturesFormDialogMode, setSubFeaturesFormDialogMode] =
    useState("add");
  const [subFeaturesToEdit, setSubFeaturesToEdit] = useState(null);
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [subFeaturesToDelete, setSubFeaturesToDelete] = useState(null);

  const toggleSubFeaturesFormDialog = (
    e,
    mode = "add",
    subFeaturesToEdit = null
  ) => {
    setSubFeaturesFormDialogOpen((prev) => !prev);
    setSubFeaturesFormDialogMode(mode);
    setSubFeaturesToEdit(subFeaturesToEdit);
  };

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setSubFeaturesToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionAdditionalFeatures.list(id), { params })
      .then((response) => {
        console.log(response.data.data);
        setSubFeaturesData(response.data.data);
        setTotalCount(response.data.data.totalCount);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      console.log("subFeaturesToDelete", subFeaturesToDelete);

      axiosInstance
        .delete(
          ApiEndPoints.ITSolutionAdditionalFeatures.delete(
            subFeaturesToDelete.id
          )
        )
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, subFeaturesToDelete, pageSize, search]
  );
  const handleCellClick = (rowData) => {
    navigate(`/it-solution-additional-features-list/${rowData.row.id}`, {
      state: rowData.row,
    });
  };
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Additional Features" />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleSubFeaturesFormDialog}>
              Add Additional Features
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            {/* <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "All" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"All"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box> */}
            <Box sx={{ p: 5 }}>
              <TableAdditionalFeatures
                search={search}
                loading={loading}
                rows={subFeaturesData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleSubFeaturesFormDialog}
                onCellClick={(rowData) => handleCellClick(rowData)}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogAdditionalFeatures
        mode={subFeaturesFormDialogMode}
        open={subFeaturesFormDialogOpen}
        toggle={toggleSubFeaturesFormDialog}
        dataToEdit={subFeaturesToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Additional Feature"
        subtitle="Are you sure you want to delete this Additional Feature?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionAdditionalFeaturesPage;
